package com.bananalab.lite;
import android.content.*;import org.json.*;import java.util.*;import java.io.*;
/** Multi-file compiled extension workspace. Generated bounded Java, not an arbitrary Java sandbox. */
final class AppJavaWorkspace{
 static final class Settings{
  JSONObject buttonColors=new JSONObject();
  int text=15,buttons=14,spacing=10,theme=0,context=3,accent=0,font=0;boolean projects=false;float jump=1,gesture=1;
  Settings copy()throws Exception{return read(json());}
  JSONObject json()throws Exception{JSONObject out=new JSONObject().put("accent",accent).put("text",text).put("buttons",buttons).put("spacing",spacing).put("theme",theme).put("context",context).put("projects",projects).put("jump",jump).put("gesture",gesture);if(font!=0)out.put("font",font);if(buttonColors.length()>0)out.put("buttonColors",buttonColors);return out;}
  static Settings read(JSONObject j)throws Exception{Settings s=new Settings();s.font=j.optInt("font",0);if(j.has("buttonColors"))s.buttonColors=new JSONObject(j.getJSONObject("buttonColors").toString());s.accent=j.optInt("accent",0);s.text=j.getInt("text");s.buttons=j.getInt("buttons");s.spacing=j.getInt("spacing");s.theme=j.getInt("theme");s.context=j.getInt("context");s.projects=j.getBoolean("projects");s.jump=(float)j.getDouble("jump");s.gesture=(float)j.getDouble("gesture");validate(s);return s;}
 }
 static volatile Settings live=new Settings();static int loaded=-1;
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-app-java",0);}
 static void validate(Settings s){if(s.font<0||s.font>4)throw new IllegalArgumentException("Fuente desconocida");if(s.buttonColors.length()>16)throw new IllegalArgumentException("Hasta16 botones personalizados");Iterator<String> labels=s.buttonColors.keys();while(labels.hasNext()){String label=labels.next();int v=s.buttonColors.optInt(label,-1);if(label.isEmpty()||label.length()>60||!label.equals(ChatLanguage.normalize(label))||v<0||v>5)throw new IllegalArgumentException("Boton o color invalido");}if(s.accent<0||s.accent>5||s.text<12||s.text>26||s.buttons<12||s.buttons>24||s.spacing<4||s.spacing>20||s.theme<0||s.theme>3||s.context<1||s.context>8||Float.isNaN(s.jump)||s.jump<.5f||s.jump>2||Float.isNaN(s.gesture)||s.gesture<.5f||s.gesture>1.8f)throw new IllegalArgumentException("Ajuste fuera del alcance probado: texto12–26, botones12–24, espacio4–20, contexto1–8, salto0.5–2, gestos0.5–1.8.");}
 static String quote(String s){return "\""+s.replace("\\","\\\\").replace("\"","\\\"")+"\"";}
 static int buttonColor(Settings s,String label){return s.buttonColors.optInt(ChatLanguage.normalize(label),s.accent);}
 static String cls(String name,String methods){return "package com.bananalab.patch;\npublic final class "+name+" {\n"+methods+"}\n";}
 static String method(String type,String name,String value){return " public static "+type+" "+name+"() { return "+value+"; }\n";}
 static Map<String,String> sources(Settings s){validate(s);Map<String,String> files=new LinkedHashMap<>();files.put("BananaBehavior.java",JavaPatchPolicy.BASE);files.put("BananaInterface.java",cls("BananaInterface",method("int","chatText",s.text+"")+method("int","buttonText",s.buttons+"")+method("int","spacing",s.spacing+"")+method("int","theme",s.theme+"")+method("boolean","projects",s.projects+"")+(s.accent==0?"":method("int","buttonAccent",s.accent+""))+(s.font==0?"":method("int","fontFamily",s.font+""))+(s.buttonColors.length()==0?"":method("String","buttonColors",quote(s.buttonColors.toString())))));files.put("BananaAnimation.java",cls("BananaAnimation",method("float","jump",s.jump+"f")+method("float","gesture",s.gesture+"f")));files.put("BananaDialogue.java",cls("BananaDialogue",method("int","contextPairs",s.context+"")));return files;}
 static JSONObject sourceJson(Settings s)throws Exception{JSONObject out=new JSONObject();for(Map.Entry<String,String> e:sources(s).entrySet())out.put(e.getKey(),e.getValue());return out;}
 static void checkSources(Settings s,JSONObject files)throws Exception{Map<String,String> expected=sources(s);if(files.length()!=expected.size())throw new IllegalArgumentException("El paquete debe contener exactamente los cuatro archivos preparados.");for(Map.Entry<String,String> e:expected.entrySet())if(!e.getValue().equals(files.getString(e.getKey())))throw new IllegalArgumentException("El código no corresponde al plan validado: "+e.getKey());}
 static Object call(ClassLoader loader,String cls,String method)throws Exception{return loader.loadClass("com.bananalab.patch."+cls).getMethod(method).invoke(null);}
 static Settings test(Class<?> root)throws Exception{ClassLoader l=root.getClassLoader();Settings s=new Settings();s.text=((Number)call(l,"BananaInterface","chatText")).intValue();s.buttons=((Number)call(l,"BananaInterface","buttonText")).intValue();s.spacing=((Number)call(l,"BananaInterface","spacing")).intValue();s.theme=((Number)call(l,"BananaInterface","theme")).intValue();try{s.accent=((Number)call(l,"BananaInterface","buttonAccent")).intValue();}catch(NoSuchMethodException legacy){s.accent=0;}try{s.buttonColors=new JSONObject((String)call(l,"BananaInterface","buttonColors"));}catch(NoSuchMethodException legacy){}try{s.font=((Number)call(l,"BananaInterface","fontFamily")).intValue();}catch(NoSuchMethodException legacy){}s.projects=(Boolean)call(l,"BananaInterface","projects");s.jump=((Number)call(l,"BananaAnimation","jump")).floatValue();s.gesture=((Number)call(l,"BananaAnimation","gesture")).floatValue();s.context=((Number)call(l,"BananaDialogue","contextPairs")).intValue();validate(s);return s;}
 static synchronized void restore(Context c){int rev=prefs(c).getInt("revision",0);if(loaded==rev)return;try{String raw=prefs(c).getString("active","");Settings s=new Settings();if(!raw.isEmpty()){JSONObject j=new JSONObject(raw);Settings planned=Settings.read(j.getJSONObject("settings"));checkSources(planned,j.getJSONObject("files"));s=test(OnDeviceJava.load(c,new File(j.getString("jar"))));if(!s.json().toString().equals(planned.json().toString()))throw new IOException("El código compilado no coincide con el plan.");}live=s;loaded=rev;}catch(Throwable failure){live=new Settings();loaded=rev;prefs(c).edit().putString("error","Recuperación: no cargué el módulo; usé los valores base. "+failure.getClass().getSimpleName()).apply();}}
 static synchronized String prepare(Context c,Settings plan,String summary)throws Exception{validate(plan);int base=prefs(c).getInt("revision",0);String old=prefs(c).getString("active","");Map<String,String> files=sources(plan);JavaChat.phase("Compilando los módulos de interfaz, animación y chat…");OnDeviceJava.Build built=OnDeviceJava.compileSources(c,files);Settings tested=test(built.type);if(!tested.json().toString().equals(plan.json().toString()))throw new IOException("La prueba del módulo no coincide con el pedido.");JSONObject draft=new JSONObject().put("settings",plan.json()).put("files",sourceJson(plan)).put("jar",built.jar.getAbsolutePath()).put("summary",summary).put("base",base).put("old",old).put("tested",true);if(prefs(c).getInt("revision",0)!=base||!prefs(c).getString("active","").equals(old))throw new IOException("La versión cambió durante la prueba.");if(!prefs(c).edit().putString("draft",draft.toString()).commit())throw new IOException("No pude guardar la prueba.");return "Compilé y probé los cuatro archivos en una copia separada.\n"+summary+"\nTodavía no está activo. Decí ‘aplica los cambios de la app’ o ‘descarta los cambios de la app’.";}
 static JSONArray history(Context c)throws Exception{return new JSONArray(prefs(c).getString("history","[]"));}
 static synchronized String apply(Context c)throws Exception{String raw=prefs(c).getString("draft","");if(raw.isEmpty())return "No hay cambios de la app pendientes.";JSONObject d=new JSONObject(raw);int rev=prefs(c).getInt("revision",0);if(rev!=d.getInt("base")||!prefs(c).getString("active","").equals(d.getString("old")))throw new IOException("La prueba quedó desactualizada. Volvé a pedir el ajuste.");Settings expected=Settings.read(d.getJSONObject("settings"));checkSources(expected,d.getJSONObject("files"));Settings tested=test(OnDeviceJava.load(c,new File(d.getString("jar"))));if(!expected.json().toString().equals(tested.json().toString()))throw new IOException("El módulo cambió desde la prueba.");JSONArray h=history(c),next=new JSONArray();for(int i=Math.max(0,h.length()-10);i<h.length();i++)next.put(h.getJSONObject(i));next.put(new JSONObject().put("id",rev).put("active",prefs(c).getString("active","")).put("summary",prefs(c).getString("summary","Valores originales")).put("time",System.currentTimeMillis()));if(!prefs(c).edit().putString("active",raw).putString("summary",d.getString("summary")).putString("history",next.toString()).putInt("revision",rev+1).putLong("changedAt",System.currentTimeMillis()).remove("draft").remove("error").commit())throw new IOException("No pude guardar la activación.");live=tested;loaded=rev+1;return "Listo. "+d.getString("summary")+"\nLos módulos probados ya están activos. Podés decir ‘deshace el ultimo cambio de la app’ o ‘versiones de la app’.";}
 static synchronized String recover(Context c,int id)throws Exception{JSONArray h=history(c);JSONObject target=null;for(int i=h.length()-1;i>=0;i--)if(h.getJSONObject(i).getInt("id")==id){target=h.getJSONObject(i);break;}if(target==null)return "No encontré esa versión entre las once versiones anteriores conservadas.";String raw=target.getString("active");Settings s=raw.isEmpty()?new Settings():Settings.read(new JSONObject(raw).getJSONObject("settings"));if(!raw.isEmpty()){JSONObject j=new JSONObject(raw);checkSources(s,j.getJSONObject("files"));Settings checked=test(OnDeviceJava.load(c,new File(j.getString("jar"))));if(!checked.json().toString().equals(s.json().toString()))throw new IOException("La versión guardada no pasó las pruebas.");}int rev=prefs(c).getInt("revision",0);JSONArray next=new JSONArray();for(int i=Math.max(0,h.length()-10);i<h.length();i++)next.put(h.getJSONObject(i));next.put(new JSONObject().put("id",rev).put("active",prefs(c).getString("active","")).put("summary",prefs(c).getString("summary","Original")).put("time",System.currentTimeMillis()));if(!prefs(c).edit().putString("active",raw).putString("summary","Recuperé la versión "+id).putString("history",next.toString()).putInt("revision",rev+1).putLong("changedAt",System.currentTimeMillis()).remove("draft").remove("error").commit())throw new IOException("No pude recuperar la versión.");live=s;loaded=rev+1;return "Recuperé la versión "+id+" de los módulos de la app. Conservé tus mensajes, escenas y personajes.";}
 static String versions(Context c)throws Exception{StringBuilder out=new StringBuilder("Módulos de la app · versión "+prefs(c).getInt("revision",0)+"\n"+prefs(c).getString("summary","Valores originales"));JSONArray h=history(c);for(int i=h.length()-1;i>=0;i--){JSONObject row=h.getJSONObject(i);out.append("\nVersión ").append(row.getInt("id")).append(": ").append(row.getString("summary"));}return out.append("\nPara recuperar: ‘volve a la version 0 de la app’ (elegí un número de la lista). Este historial es independiente de las escenas y del Java de celebración.").toString();}
 static int background(){return new int[]{0xff141922,0xff142638,0xff182c25,0xff291d36}[live.theme];}
 static float jumpLift(float lift){return lift*ModularHub.view().jump;}
}
